def config_value(text: str, key: str) -> str:
    """Return the value for `key` in a `name=value` per-line config text.

    Each line is split on its first "=", and whitespace around the name and
    the value is stripped. Values may contain "=". Lines without "=" and
    blank lines are ignored. If the key appears more than once, the last
    occurrence wins. Key matching is exact and case-sensitive. Returns ""
    when the key is absent. Does not read files.
    """
    result = ""
    for line in text.splitlines():
        name, sep, value = line.partition("=")
        if not sep:
            continue
        if name.strip() == key:
            result = value.strip()
    return result


def test_basic_lookup() -> None:
    assert config_value("a=1\nb=2\nc=3", "b") == "2"


def test_missing_key_returns_empty_string() -> None:
    assert config_value("a=1\nb=2", "z") == ""


def test_empty_text() -> None:
    assert config_value("", "a") == ""


def test_empty_value_is_empty_string() -> None:
    assert config_value("a=\nb=2", "a") == ""


def test_whitespace_stripped_around_name_and_value() -> None:
    assert config_value("  a  =  hello world  \n", "a") == "hello world"


def test_value_may_contain_equals() -> None:
    assert config_value("url=http://x/?q=1", "url") == "http://x/?q=1"


def test_lines_without_equals_ignored() -> None:
    assert config_value("junk\n\na=1", "a") == "1"
    assert config_value("junk", "junk") == ""


def test_duplicate_key_last_wins() -> None:
    assert config_value("a=1\na=2", "a") == "2"


def test_key_is_case_sensitive_and_exact() -> None:
    assert config_value("Key=1", "key") == ""
    assert config_value("keyword=1", "key") == ""
    assert config_value("key=1", "keyword") == ""


def test_handles_crlf_line_endings() -> None:
    assert config_value("a=1\r\nb=2\r\n", "b") == "2"


def test_key_not_matched_inside_value() -> None:
    assert config_value("a=b=c", "b") == ""

